    'PG-32-tag': [
        ('PRD-FR-001：合成查询功能，不代表真实业务'.encode(), 'PRD-FR-001：【推断】合成查询功能，不代表真实业务'.encode()),
        ('<!-- prd:section residuals -->\n无适用遗留项\n<!-- /prd:section -->'.encode(), '<!-- prd:section residuals -->\n- SYNTHETIC-PRD/FR-1（PRD-FR-001）：【推断】合成查询功能，不代表真实业务；该内容尚待验证，建议返回需求分析确认。\n<!-- /prd:section -->'.encode())
    ]
}
for scenario, replacements in edits.items():
    data = (root / 'workspace' / scenario / 'prd' / 'prd.md').read_bytes()
    for old, new in replacements:
        if data.count(old) != 1:
            raise ValueError(f'{scenario}: 定向替换必须唯一')
        data = data.replace(old, new, 1)
    (root / 'artifacts' / scenario / 'body-candidate-1.md').write_bytes(data)
